const items = $input.all();
const results = [];

for (const item of items) {
  const url = item.json['Ссылка'] || '';
  // Extract username from URL like https://www.instagram.com/username/ or /username/?g=5
  const match = url.match(/instagram\.com\/([^\/?]+)/);
  const username = match ? match[1] : null;

  if (username) {
    results.push({
      json: {
        ...item.json,
        username: username,
        row_number: item.json['row_number'] || items.indexOf(item) + 2
      }
    });
  }
}

return results;

const items = $input.all();
const prevItems = $('Extract Username').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const prev = prevItems[i].json;
  const resp = items[i].json;
  const username = prev.username;

  // Check for errors
  if (resp.error) {
    results.push({json: {
      original_url: prev['Ссылка'],
      'Аккаунт Instagram': '@' + username,
      'Имя / Название салона': '',
      'Город': '',
      'Ніша': '',
      'Подписчики': '',
      'Есть ссылка на запись?': '',
      'Комментарий': resp.error.message || JSON.stringify(resp.error)
    }});
    continue;
  }

  // Extract profile data from business_discovery response
  const profile = resp.business_discovery || resp;
  const bio = profile.biography || '';
  const name = profile.name || '';
  const followers = profile.followers_count || '';
  const website = profile.website || '';

  const bl = (bio + ' ' + name + ' ' + username).toLowerCase();

  // Detect city
  let city = '';
  [['київ','Київ'],['kyiv','Київ'],['харків','Харків'],['kharkiv','Харків'],['kharkov','Харків'],
   ['одес','Одеса'],['львів','Львів'],['дніпро','Дніпро'],['запоріж','Запоріжжя'],
   ['полтав','Полтава'],['вінниц','Вінниця']].forEach(([k,v]) => {
    if (!city && bl.includes(k)) city = v;
  });

  // Detect niche
  let niche = '';
  [['nail','Нігті'],['нігт','Нігті'],['манікю','Нігті'],['гель','Нігті'],['педікю','Нігті'],
   ['brow','Брови'],['бров','Брови'],['lash','Вії'],['вії','Вії'],
   ['hair','Волосся'],['волос','Волосся'],['beauty','Салон'],['краси','Салон'],
   ['косметолог','Косметологія'],['масаж','Масаж'],['massage','Масаж']].forEach(([k,v]) => {
    if (!niche && bl.includes(k)) niche = v;
  });

  // Check for booking link
  let hasBooking = 'ні';
  if (website) {
    const wl = website.toLowerCase();
    hasBooking = ['booking','calendly','taplink','linktree','mssg.me','yclients','dikidi','lnk.bio','linktr.ee','solo.to'].some(k => wl.includes(k)) ? 'так' : 'є посилання';
  }

  results.push({json: {
    original_url: prev['Ссылка'],
    'Аккаунт Instagram': '@' + username,
    'Имя / Название салона': name,
    'Город': city,
    'Ніша': niche,
    'Подписчики': followers ? String(followers) : '',
    'Есть ссылка на запись?': hasBooking,
    'Комментарий': bio.substring(0, 200)
  }});
}

return results;
